-- Focused SOURCE-ONLY authorization/privacy checks; root applies and runs locally.
begin;
do $$
declare own uuid;manager uuid;cashier uuid;foreign_worker uuid;customer uuid;br uuid:=gen_random_uuid();foreign_br uuid:=gen_random_uuid();foreign_receipt jsonb;service uuid:=gen_random_uuid();other_service uuid:=gen_random_uuid();r_manager jsonb;r_cashier jsonb;notice jsonb;v jsonb;denied boolean;today date:=(clock_timestamp()at time zone'Africa/Cairo')::date;
begin
 select user_id into strict own from public.staff_profiles where role='owner'and is_active limit 1;
 select user_id into strict manager from public.staff_profiles where role='manager'and is_active limit 1;
 select user_id into strict cashier from public.staff_profiles where role='employee'and is_active limit 1;
 select user_id into strict foreign_worker from public.staff_profiles where role='employee'and is_active and user_id<>cashier limit 1;
 select id into strict customer from public.customers c where not exists(select 1 from public.staff_profiles s where s.user_id=c.id)limit 1;
 insert into public.business_branches(branch_id,name_ar,name_en)values(br,'اختبار سياق الاستقبال','Reception context QA'),(foreign_br,'فرع آخر','Other context QA');
 insert into public.staff_branch_access(user_id,branch_id)values(manager,br),(cashier,br);
 update public.staff_profiles set permissions=permissions||'{"cashier":true}'where user_id=cashier;
 insert into private.hr_employment(staff_id,salary,commission_percent,currency,starts_on)values(cashier,1234,17.5,'EGP',today-1)on conflict(staff_id)do update set salary=1234,commission_percent=17.5,currency='EGP',starts_on=today-1,ends_on=null;
 insert into public.business_catalog_items(item_id,branch_id,item_type,name,price,is_active,is_public)values(service,br,'service','Actual context service',137.45,true,true),(other_service,br,'service','Hidden context service',200,true,false);
 notice:=jsonb_build_object('accepted',true,'version','offline-registration-v1','language','en','text',private.offline_registration_notice('en'));
 execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',manager::text,true);
 r_manager:=public.register_offline_customer(gen_random_uuid(),br,'QA manager reception','010'||lpad((abs(hashtextextended(gen_random_uuid()::text,0))%100000000)::text,8,'0'),'EG',jsonb_build_object('plate_number','QA-CONTEXT-'||left(gen_random_uuid()::text,8)),notice);
 v:=public.get_offline_walk_in_context((r_manager->>'request_id')::uuid);
 assert v->>'can_prepare'='true'and v->'bound_cashier'->>'id'=manager::text;
 assert v->'subject'->>'name'='QA manager reception'and v->'subject'->>'identity_verified'='false';
 assert exists(select 1 from jsonb_array_elements(v->'services')s where s->>'id'=service::text and(s->>'price')::numeric=137.45);
 assert not exists(select 1 from jsonb_array_elements(v->'services')s where s->>'id'=other_service::text);
 assert exists(select 1 from jsonb_array_elements(v->'workers')w where w->>'id'=cashier::text and w-array['id','name']='{}');
 assert not exists(select 1 from jsonb_array_elements(v->'workers')w where w->>'id'=foreign_worker::text);
 assert (v->'subject')-array['profile_id','name','car_ref_id','plate_number','brand','model','identity_verified']='{}';
 assert (v->'bound_cashier')-array['id','name']='{}';
 assert (v->'branch')-array['id','name_ar','name_en','currency']='{}';
 assert not exists(select 1 from jsonb_array_elements(v->'workers')w where w-array['id','name']<>'{}');
 assert not exists(select 1 from jsonb_array_elements(v->'services')s where s-array['id','name','name_en','vehicle_type','price','duration_minutes']<>'{}');
 assert v-array['registration_request_id','branch','subject','bound_cashier','can_prepare','services','workers','capabilities']='{}';
 perform set_config('request.jwt.claim.sub',cashier::text,true);
 denied:=false;begin perform public.get_offline_walk_in_context((r_manager->>'request_id')::uuid);exception when insufficient_privilege then denied:=true;end;assert denied,'Employee saw another cashier receipt';
 r_cashier:=public.register_offline_customer(gen_random_uuid(),br,'QA cashier reception','010'||lpad((abs(hashtextextended(gen_random_uuid()::text,0))%100000000)::text,8,'0'),'EG',jsonb_build_object('plate_number','QA-OWN-'||left(gen_random_uuid()::text,8)),notice);
 v:=public.get_offline_walk_in_context((r_cashier->>'request_id')::uuid);
 assert v->>'can_prepare'='false'and v->'bound_cashier'->>'id'=cashier::text and v->'workers'='[]'and v->'services'='[]','Employee acquired assignment candidates';
 perform set_config('request.jwt.claim.sub',own::text,true);
 v:=public.get_offline_walk_in_context((r_cashier->>'request_id')::uuid);assert v->>'can_prepare'='true'and v->'bound_cashier'->>'id'=cashier::text,'Owner guessed another cashier';
 foreign_receipt:=public.register_offline_customer(gen_random_uuid(),foreign_br,'QA other branch','010'||lpad((abs(hashtextextended(gen_random_uuid()::text,0))%100000000)::text,8,'0'),'EG',jsonb_build_object('plate_number','QA-OTHER-'||left(gen_random_uuid()::text,8)),notice);
 perform set_config('request.jwt.claim.sub',manager::text,true);
 denied:=false;begin perform public.get_offline_walk_in_context((foreign_receipt->>'request_id')::uuid);exception when insufficient_privilege then denied:=true;end;assert denied,'Manager crossed branch scope';
 perform set_config('request.jwt.claim.sub',customer::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',customer,'user_metadata',jsonb_build_object('role','owner'))::text,true);
 denied:=false;begin perform public.get_offline_walk_in_context((r_cashier->>'request_id')::uuid);exception when insufficient_privilege then denied:=true;end;assert denied;
 perform set_config('request.jwt.claim.sub',manager::text,true);
 denied:=false;begin perform public.get_offline_walk_in_context(gen_random_uuid());exception when insufficient_privilege then denied:=true;end;assert denied,'Unknown receipt became a directory';
 execute 'reset role';
 assert not has_function_privilege('anon','public.get_offline_walk_in_context(uuid)','EXECUTE');
 assert not has_function_privilege('service_role','private.get_offline_walk_in_context(uuid)','EXECUTE');
 raise notice 'PASS actual receipt/cashier binding, manager worker/service eligibility, employee own-only no candidates, no salary/rate/contact/history disclosure';
end$$;
rollback;
